import cv2,numpy as np
x=np.load('source_pixels.npz')['rgb']
cs=[]
for t,a in enumerate(x):
 r,g,b=a.transpose(2,0,1).astype(int)
 # gray/blue/pink ball excludes green and small orange projectile
 fg=(((r-g)>22)|((b-g)>18)|(r>145)|(b>145)|(g<65)).astype('uint8')
 fg[:65]=0; fg[98:]=0; fg[:,:45]=0; fg[:,150:]=0
 n,lab,st,ce=cv2.connectedComponentsWithStats(fg,8)
 cand=[]
 for i in range(1,n):
  xx,yy,w,h,ar=st[i]
  if ar>60: cand.append((ar,i))
 if cand:
  _,i=max(cand); xx,yy,w,h,ar=st[i]; c=ce[i]; cs.append((t,round(c[0],2),round(c[1],2),xx,yy,w,h,ar))
 else: cs.append((t,None))
for q in cs: print(*q)
